                pergunta: "Um servidor alega ter direito a um benefício previdenciário. Qual artigo do Estatuto define o regime de provimento e vacância?",
                alternativas: { A: "Art. 15", B: "Art. 40", C: "Art. 88", D: "Art. 120" },
                respostaCorreta: "B"
            },
            // Adicione mais 18 questões seguindo este formato...
            {
                pergunta: "Sobre os deveres do servidor, é correto afirmar que ele deve:",
                alternativas: { A: "Priorizar interesses particulares", B: "Cumprir ordens ilegais", C: "Lealdade e assiduidade", D: "Revelar sigilo funcional" },
