            },
            {
                pergunta: "Em caso de afastamento por licença para tratamento de saúde, qual é o prazo máximo estabelecido pelo Estatuto para a concessão do benefício?",
                alternativas: { A: "6 meses", B: "1 ano", C: "Determinado em regulamento", D: "Indeterminado" },
