            questoes.forEach((q, index) => {
                const qNum = index + 1;
                let htmlQuestao = `
                    <div class="questao" id="questao-${qNum}">
                        <p>Questão ${qNum}: ${q.pergunta}</p>
                        <div class="alternativas">
                `;

                // Gera as opções de A a D
                Object.keys(q.alternativas).forEach(key => {
                    // Usamos um input radio para garantir apenas uma seleção por questão
                    htmlQuestao += `
                        <label for="q${qNum}-${key}">
                            <input type="radio" id="q${qNum}-${key}" name="resposta${qNum}" value="${key}">
                            <strong>${key})</strong> ${q.alternativas[key]}
                        </label>
                    `;
                });

                htmlQuestao += `
                        </div>
                    </div>
                `;
                container.innerHTML += htmlQuestao;
            });
        }

        // --- 📊 FUNÇÃO DE CORREÇÃO E EXIBIÇÃO DE RESULTADO ---
        function corrigirSimulado() {
            let pontuacao = 0;

            questoes.forEach((q, index) => {
                const qNum = index + 1;
                // 1. Captura a resposta selecionada pelo usuário
                const radios = document.getElementsByName(`resposta${qNum}`);
                let respostaUsuario = null;
                radios.forEach(radio => {
                    if (radio.checked) {
                        respostaUsuario = radio.value;
                    }
                });

                const questaoElement = document.getElementById(`questao-${qNum}`);
                const alternativasElement = questaoElement.querySelector('.alternativas');

                // 2. Verifica a resposta
                const correta = respostaUsuario === q.respostaCorreta;

                if (correta) {
                    pontuacao++;
                    // Marca a alternativa correta em verde
                    alternativasElement.querySelector(`input[value="${q.respostaCorreta}"]`).closest('label').classList.add('correta');
                } else {
                    // Marca a alternativa selecionada pelo usuário em vermelho (se selecionou algo)
                    if (respostaUsuario) {
                        alternativasElement.querySelector(`input[value="${respostaUsuario}"]`).closest('label').classList.add('incorreta');
                    }
                    // SEMPRE marca a alternativa correta para fins de aprendizado
                    alternativasElement.querySelector(`input[value="${q.respostaCorreta}"]`).closest('label').classList.add('correta');
                }

                // 3. Marca a seleção do usuário
                if (respostaUsuario) {
                    alternativasElement.querySelector(`input[value="${respostaUsuario}"]`).closest('label').classList.add('selecionada');
                }

                // Garante que a alternativa correta tenha o estilo de correção, mesmo que o usuário não tenha respondido
                alternativasElement.querySelector(`input[value="${q.respostaCorreta}"]`).closest('label').classList.add('correta');
            });

            // Exibe o resultado
            notaFinalDiv.textContent = `${pontuacao} / 20`;
            resultadoDiv.style.display = 'block';

            // Opcional: Rola a tela para o resultado
            resultadoDiv.scrollIntoView({ behavior: 'smooth' });
        }

        // --- ⚙️ EVENT LISTENERS ---
        btnEnviar.addEventListener('click', corrigirSimulado);

        // Inicia o carregamento do simulado ao abrir a página
        renderizarSimulado();
    </script>
</body>
</html>
