      setRefresh(!refresh);
      setEditMode({ ...editMode, [purchase._id]: false });
    } catch (error) {
      console.log(error);
    }
  };

  const handleEditChange = (id, field, value) => {
    setPurchases(prevState => {
      const updatedPurchase = prevState.find(purchase => purchase._id === id);
      if (field === "valueTotal") {
        updatedPurchase[field] = removeCurrencyMask(value);
      } else if (field === "data") {
        updatedPurchase[field] = convertDate(value);
      } else {
        updatedPurchase[field] = value;
      }
      // ATENÇÃO: Você precisa garantir que a atualização em prevState reflita a mudança no array
      // O código original estava apenas logando e retornando prevState, o que não atualiza o estado.
      return prevState.map(p => p._id === id ? {...p, [field]: updatedPurchase[field]} : p);
    });
  };

  const deletePurchase = async (id) => {
    try {
      await api.delete(`/compras/${id}`);
      setRefresh(!refresh);
    } catch (error) {
      console.error(error);
    }
  };  

  const updateTrackingStatus = (purchaseId, status) => {
    setTrackingStatus(prevState => ({
