  const archivePurchase = async (id) => {
    try {
      // **IMPORTANTE:** Substitua /compras/${id}/archive pelo endpoint real do seu backend
      await api.post(`/compras/${id}/archive`); 

      // Atualiza a lista para remover/esconder a compra arquivada
      setRefresh(!refresh); 
    } catch (error) {
      console.error("Erro ao arquivar a compra:", error);
    }
  };

  function removeCurrencyMask(value) {
    // Remove espaços, a literal "R$" e o separador de milhar (",")
    return value.replace(/\s|R\$/g, "").replace(",", ".");
  }

  function convertDate(dateString) {
    const parts = dateString.split('/');
    const day = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10);
    const year = parseInt(parts[2], 10);
    return new Date(year, month - 1, day);
  }

  return (
